export function weatherTallyNotes(state){
 const w=weatherView(state,null),t=tallyView(state),weatherOwn=Object.prototype.hasOwnProperty.call(state,'weather'),tallyOwn=Object.prototype.hasOwnProperty.call(state,'dataDesk');
 if(!weatherOwn&&!tallyOwn)return '';
 const weather=`<h3>Reported weather choices</h3>${w.entries.length?`<ul>${w.entries.map(e=>`<li>${esc(e.date)}: reported ${esc(label(e.weather))}</li>`).join('')}</ul>`:'<p>No readable reported weather choices.</p>'}<p>${weatherAbout}</p>${weatherOwn?rawDetails(state.weather,'Original weather entries, including earlier unreadable values'):''}`;
 const sheets=t.sheets.map(item=>{if(!item.readable||item.ambiguous)return '<p>Earlier sheet retained. Its original stays in your notes.</p>';const v=tallyView(state,item.id);return `<article class="wt-notes-sheet"><h4>${esc(v.source?.title??item.id)} · ${esc(item.id)}</h4><p>${v.source?.kind==='practice'?'Made-up practice source':'Reported weather choices'}</p>${v.source?`<p>Frozen source: ${v.source.days.length} reports · ${v.source.categories.map(c=>esc(c.label)).join(' · ')}</p>`:''}${v.placements?`<p>${v.kept?'Kept marks':'Current marks'}: ${v.source.categories.map(c=>`${esc(c.label)} ${v.counts[c.code]}`).join(' · ')}. ${v.placements.length} of ${v.source.days.length} cards counted.</p>`:''}${v.kept?supportText(v.kept.support):v.mutable?supportText(v.sheet.support):'<p>Earlier unreadable values retained.</p>'}${v.checks.length?`<h5>Earlier aggregate comparisons</h5>${v.checks.map(c=>`<p>${esc(c.source.title)} · ${c.placements.length} of ${c.source.days.length} cards · recorded complete: ${c.complete?'yes':'no'} · recorded aggregate match: ${c.matches?'yes':'no'}.</p>${supportText(c.supportBefore)}`).join('')}`:''}</article>`;}).join('');
 return `<section class="wt-notes"><h2>Weather notes and tally sheets</h2>${weather}<h3>Tally sheets</h3>${t.status==='unsupported'?'<p>This earlier tally notebook cannot be opened here. Its original stays in your notes.</p>':sheets||'<p>No tally sheets have been started.</p>'}<p>${tallyAbout}</p>${tallyOwn?rawDetails(state.dataDesk,'Original tally sheets, checks and earlier unreadable values'):''}</section>`;
}
